suppressPackageStartupMessages(library(data.table));arg<-sub('^--file=','',grep('^--file=',commandArgs(),value=TRUE)[1]);out<-normalizePath(file.path(dirname(arg),'..'));src<-dirname(out);.libPaths(c(.libPaths(),file.path(src,'03_lee_fig3_style_FINAL/hallmark_GSEA_Q4_vs_Q1_26.08.26/R_libs')));library(fgsea);m<-readRDS(file.path(out,'resources/models/Epithelial_post_group.rds'));pp<-readRDS(file.path(out,'resources/outcome_prepared.rds'));a<-fread(file.path(out,'results/tables/03_HR_selected_plotdata.csv'));audit<-list()
